INSERT INTO `afront_contact` VALUES (27, 'Ue4d1f4e3abdeab58ce78f8316eb7bc62', NULL, 'ATP.', 'พฤกษา 33', 0, 0, '2025-06-01 08:28:47', '', 'IN', 'ps33_683baccf8ee270.38895640', 'รบกวนสอบถามครับ ถ้าผมจะขอนำรถขนส่งเหล็กกล่องเข้าหมู่บ้าน โดยขนส่งเหล็กจำนวน 8 เส้น ผมสามารถแจ้ง รปภ. ได้เลย หรือต้องแจ้ง ตรงนี้ เพื่อทราบ และนำเหล็กเข้าพื้นที่หมู่บ้านได้ครับ', 'ให้แจ้ง รปภ ว่าไปบ้านไหนค่ะ ', 'อรรถพล', 'ถมยาแก้ว', '67/63', '-', '-', '-', 'Y', '2025-06-01 08:28:47', '2025-06-01 08:28:47', '-', '-', '', 'N');
