INSERT INTO `ims_line_webhook_messages` VALUES (26359, '621571940251075021', 'Ued4a58198892233441a5347caad5aefa', 'สต.นเรศ  ดอนเทศ', NULL, NULL, NULL, NULL, 'text', '6/07/69 รายงานการเข้าตรวจ\n\nเรียน : ผู้บริหารและผู้จัดการฝ่ายทราบ... สายตรวจได้เข้าตรวจการปฏิบัติหน้าที่  รปภ.\n\nผลัดกลางวัน จำนวน 1 นาย\n\nหน่วยงาน : หมู่บ้านพฤกษา 33\n\nมีรายละเอียดกำชับดังนี้....\n_คัดกรองรถผู้มาติดต่อแลกบัตรบันทึกเข้านะบบ\n-เน้นย้ำการปฏิบัติหน้าที่อย่างเคร่งครัด \n-เน้นย้ำเรื่องห้ามทิ้งจุดปฏิบัติการโดยเด็ดขาด\n-เน้นย้ำห้ามเล่นโทรศัพท์ในขณะปฏิบัติหน้าที่\n-เน้นย้ำการแต่งกายให้เรียบร้อยสะอาด\n-เน้นย้ำเรื่องเข้างานตรงต่อเวลา\n-ห้ามพาบุคคลภายนอกผู้ไม่มีส่วนเกี่ยวข้องเข้าพื้นที่\n     จึงเรียนมาเพื่อทราบ\n       นเรศ  ดอนเทศ\n( สายตรวจฝ่ายปฏิบัติการ )\n     📞 06-30590194', '', 'Cd6b5e1dfc01ac62b37a7f84e9a951ae2', 'N', '2026-07-06 12:50:52', 0, NULL);
INSERT INTO `ims_line_webhook_messages` VALUES (26360, '621571948270846293', 'Ued4a58198892233441a5347caad5aefa', 'สต.นเรศ  ดอนเทศ', NULL, NULL, NULL, NULL, 'image', 'ส่งรูปภาพ', '621571948270846293.jpg', 'Cd6b5e1dfc01ac62b37a7f84e9a951ae2', 'N', '2026-07-06 12:50:56', 0, NULL);
