INSERT INTO `ims_vote_topic` VALUES (2, 'โหวตเพื่อขอประชามติตามความต้องการของลูกบ้านเพื่อนำมาประกอบการตัดสินใจในการดำเนินงาน', 'เพื่อให้เป็นมติที่มีความยุติธรรมสมาชิกสามารถเลือกความจำนงของลูกบ้านเลือกข้อที่ต้องการ\r\n1 บ้านเลขที่ 1 สิทธิในการโหวต บ้านที่โหวตในกลุ่มไลน์พฤกษา 33 ไม่ต้องโหวตซ้ำค่ะ ขอบพระคุณค่ะ', 'active', '2026-07-14 14:52:19');
