-- ----------------------------
-- Table structure for ims_bank_account
-- ----------------------------
DROP TABLE IF EXISTS `ims_bank_account`;
CREATE TABLE `ims_bank_account`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `account_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'รหัสอ้างอิงบัญชีภายในระบบ (เช่น ACC-001)',
  `account_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'ชื่อบัญชี เช่น บัญชีออมทรัพย์โครงการ',
  `bank_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'ธนาคาร เช่น กสิกรไทย, ไทยพาณิชย์',
  `account_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'เลขที่บัญชีธนาคาร',
  `branch_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'สาขาของธนาคาร',
  `opening_balance` decimal(15, 2) NOT NULL DEFAULT 0.00 COMMENT 'ยอดยกมาเริ่มต้น ณ วันที่ระบุ',
  `opening_date` date NOT NULL COMMENT 'วันที่บันทึกยอดยกมาเริ่มต้น',
  `current_balance` decimal(15, 2) NOT NULL DEFAULT 0.00 COMMENT 'ยอดคงเหลือสะสมปัจจุบัน',
  `status` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'Y' COMMENT 'สถานะการใช้งาน (Y = ใช้งาน, N = ยกเลิก)',
  `created_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_account_code`(`account_code` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

