-- Records of ims_bank_account
-- ----------------------------

-- ----------------------------
-- Table structure for ims_bank_transaction
-- ----------------------------
DROP TABLE IF EXISTS `ims_bank_transaction`;
CREATE TABLE `ims_bank_transaction`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `bank_account_id` int NOT NULL COMMENT 'รหัสเชื่อมโยงไปยัง ims_bank_account',
  `doc_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'เลขที่เอกสารบันทึกรายการ (เช่น TXN-202606-0001)',
  `transaction_date` datetime NOT NULL COMMENT 'วันเวลาที่ทำรายการจริงในสลิป',
  `transaction_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'ประเภทรายการ: DEPOSIT, WITHDRAW, ADJUST_ADD, ADJUST_SUB, INTEREST, FEE',
  `amount` decimal(15, 2) NOT NULL COMMENT 'จำนวนเงิน',
  `fee` decimal(15, 2) NOT NULL DEFAULT 0.00 COMMENT 'ค่าธรรมเนียมธนาคารในการทำรายการ (ถ้ามี)',
  `ref_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'เลขที่อ้างอิงสลิปโอนเงิน / เลขที่เช็ค',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'รายละเอียดการทำรายการ / หมายเหตุ',
  `picture_slip` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'พาธจัดเก็บไฟล์สลิป/หลักฐานการโอน',
  `status` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'Y' COMMENT 'สถานะรายการ (Y = สำเร็จ, N = รออนุมัติ, C = ยกเลิก)',
  `created_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_doc_no`(`doc_no` ASC) USING BTREE,
  INDEX `idx_account_txn`(`bank_account_id` ASC) USING BTREE,
  INDEX `idx_txn_date`(`transaction_date` ASC) USING BTREE,
  INDEX `idx_txn_type`(`transaction_type` ASC) USING BTREE,
  CONSTRAINT `fk_bank_transaction_account` FOREIGN KEY (`bank_account_id`) REFERENCES `ims_bank_account` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

