-- ----------------------------
-- Table structure for ims_visitor_contact
-- ----------------------------
DROP TABLE IF EXISTS `ims_visitor_contact`;
CREATE TABLE `ims_visitor_contact`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `house_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'บ้านเลขที่ (อ้างอิงจาก ims_house_master.house_number)',
  `visitor_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'ชื่อผู้มาติดต่อ',
  `phone_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'เบอร์โทรศัพท์',
  `license_plate` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'เลขทะเบียนรถ',
  `visitor_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'ประเภท (ลูกบ้าน/ช่าง/แขก/ญาติ/อื่นๆ)',
  `purpose` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'วัตถุประสงค์',
  `card_exchange` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'N' COMMENT 'Y=แลกแล้ว, N=ยังไม่ได้แลก',
  `card_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'หมายเลขบัตร',
  `card_exchange_date` datetime NULL DEFAULT NULL COMMENT 'วันที่แลกบัตร',
  `check_in_datetime` datetime NULL DEFAULT NULL COMMENT 'เวลาเข้า',
  `check_out_datetime` datetime NULL DEFAULT NULL COMMENT 'เวลาออก',
  `check_in_by` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'ผู้ให้เข้า',
  `check_out_by` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'ผู้ให้ออก',
  `check_in_status` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'N' COMMENT 'Y=เช็คอินแล้ว, N=ยังไม่ได้เช็คอิน',
  `picture_1` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'รูปภาพ 1',
  `picture_2` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'รูปภาพ 2',
  `picture_3` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'รูปภาพ 3',
  `picture_4` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'รูปภาพ 4',
  `picture_5` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'รูปภาพ 5',
  `note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'หมายเหตุ',
  `create_by` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'ผู้สร้าง',
  `create_datetime` datetime NULL DEFAULT current_timestamp() COMMENT 'วันที่สร้าง',
  `update_by` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'ผู้แก้ไข',
  `update_datetime` datetime NULL DEFAULT NULL COMMENT 'วันที่แก้ไข',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_house_number`(`house_number` ASC) USING BTREE,
  INDEX `idx_card_no`(`card_no` ASC) USING BTREE,
  INDEX `idx_check_in_status`(`check_in_status` ASC) USING BTREE,
  INDEX `idx_check_in_datetime`(`check_in_datetime` ASC) USING BTREE,
  INDEX `idx_check_out_datetime`(`check_out_datetime` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'ติดต่อลูกบ้าน - ผู้มาติดต่อ' ROW_FORMAT = Dynamic;

