-- Records of ims_visitor_contact
-- ----------------------------

-- ----------------------------
-- Table structure for ims_vote_option
-- ----------------------------
DROP TABLE IF EXISTS `ims_vote_option`;
CREATE TABLE `ims_vote_option`  (
  `option_id` int NOT NULL AUTO_INCREMENT,
  `topic_id` int NOT NULL COMMENT 'ไอดีอ้างอิงตารางหัวข้อโหวต',
  `option_text` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ข้อความเนื้อหาตัวเลือกคำตอบ',
  PRIMARY KEY (`option_id`) USING BTREE,
  INDEX `topic_id`(`topic_id` ASC) USING BTREE,
  CONSTRAINT `ims_vote_option_ibfk_1` FOREIGN KEY (`topic_id`) REFERENCES `ims_vote_topic` (`topic_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'ตารางรายการตัวเลือกคำตอบประชามติ' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ims_vote_option
-- ----------------------------

-- ----------------------------
-- Table structure for ims_vote_record
-- ----------------------------
DROP TABLE IF EXISTS `ims_vote_record`;
CREATE TABLE `ims_vote_record`  (
  `vote_id` int NOT NULL AUTO_INCREMENT,
  `topic_id` int NOT NULL COMMENT 'ไอดีอ้างอิงตารางหัวข้อโหวต',
  `house_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'บ้านเลขที่ของลูกบ้านที่ใช้สิทธิ์',
  `option_id` int NOT NULL COMMENT 'ไอดีตัวเลือกที่เลือกโหวต',
  `voted_at` timestamp NOT NULL DEFAULT current_timestamp() COMMENT 'วันเวลาที่บันทึกโหวต',
  PRIMARY KEY (`vote_id`) USING BTREE,
  UNIQUE INDEX `uq_topic_house`(`topic_id` ASC, `house_number` ASC) USING BTREE,
  INDEX `option_id`(`option_id` ASC) USING BTREE,
  CONSTRAINT `ims_vote_record_ibfk_1` FOREIGN KEY (`topic_id`) REFERENCES `ims_vote_topic` (`topic_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `ims_vote_record_ibfk_2` FOREIGN KEY (`option_id`) REFERENCES `ims_vote_option` (`option_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 114 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'ตารางบันทึกคะแนนประชามติแยกตามบ้านเลขที่' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of ims_vote_record
-- ----------------------------

-- ----------------------------
-- Table structure for ims_vote_topic
-- ----------------------------
DROP TABLE IF EXISTS `ims_vote_topic`;
CREATE TABLE `ims_vote_topic`  (
  `topic_id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'หัวข้อการโหวต / ประเด็นประชามติ',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'รายละเอียดข้อมูลประกอบคำอธิบาย',
  `status` enum('active','inactive') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'active' COMMENT 'สถานะหัวข้อโหวต (active = เปิดโหวต, inactive = ปิดโหวต)',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp() COMMENT 'วันที่เวลาสร้างหัวข้อ',
  PRIMARY KEY (`topic_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'ตารางหัวข้อประชามติหลัก' ROW_FORMAT = Dynamic;

