DROP TABLE IF EXISTS `visits`;
CREATE TABLE `visits`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `visitor_id` int NOT NULL COMMENT 'ID ผู้มาเยือ',
  `house_id` int NOT NULL COMMENT 'ID บ้านที่เข้าพบ',
  `check_in_time` datetime NULL DEFAULT current_timestamp() COMMENT 'เวลาเข้า',
  `check_out_time` datetime NULL DEFAULT NULL COMMENT 'เวลาออก',
  `status` enum('pending','approved','rejected','checked_in','checked_out','cancelled') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'pending' COMMENT 'สถานะ',
  `approval_method` enum('line','app','gate') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'วิธีอนุญาต',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'หมายเหตุ',
  `created_at` datetime NULL DEFAULT current_timestamp(),
  `updated_at` datetime NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `visitor_id`(`visitor_id` ASC) USING BTREE,
  INDEX `house_id`(`house_id` ASC) USING BTREE,
  INDEX `idx_check_in`(`check_in_time` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  CONSTRAINT `visits_ibfk_1` FOREIGN KEY (`visitor_id`) REFERENCES `visitors` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION,
  CONSTRAINT `visits_ibfk_2` FOREIGN KEY (`house_id`) REFERENCES `houses` (`id`) ON DELETE CASCADE ON UPDATE NO ACTION
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

