DROP VIEW IF EXISTS `v_checkins`;
CREATE VIEW `v_checkins` AS select `checkins`.`id` AS `id`,`checkins`.`user_id` AS `user_id`,`checkins`.`display_name` AS `display_name`,`checkins`.`place_name` AS `place_name`,`checkins`.`latitude` AS `latitude`,`checkins`.`longitude` AS `longitude`,`checkins`.`checkin_time` AS `checkin_time`,`checkins`.`photo_path` AS `photo_path`,`checkins`.`check_type` AS `check_type`,`checkins`.`token_checkin` AS `token_checkin`,`checkins`.`remark` AS `remark`,`ims_employee_line_user`.`line_picture_profile` AS `line_picture_profile`,`ims_employee_line_user`.`emp_name` AS `emp_name` from (`checkins` left join `ims_employee_line_user` on(`ims_employee_line_user`.`line_user_id` = `checkins`.`user_id`));

-- ----------------------------
-- View structure for v_checkins_time
-- ----------------------------
DROP VIEW IF EXISTS `v_checkins_time`;
CREATE VIEW `v_checkins_time` AS with ranked_checkins as (select `c`.`id` AS `id`,`c`.`user_id` AS `user_id`,`c`.`display_name` AS `display_name`,`c`.`place_name` AS `place_name`,`c`.`latitude` AS `latitude`,`c`.`longitude` AS `longitude`,`c`.`checkin_time` AS `checkin_time`,`c`.`photo_path` AS `photo_path`,`c`.`check_type` AS `check_type`,`c`.`token_checkin` AS `token_checkin`,`c`.`remark` AS `remark`,`e`.`line_picture_profile` AS `line_picture_profile`,`e`.`emp_name` AS `emp_name`,cast(`c`.`checkin_time` as date) AS `checkin_date`,row_number() over ( partition by `c`.`user_id`,cast(`c`.`checkin_time` as date) order by `c`.`checkin_time`) AS `rn_asc`,row_number() over ( partition by `c`.`user_id`,cast(`c`.`checkin_time` as date) order by `c`.`checkin_time` desc) AS `rn_desc` from (`checkins` `c` left join `ims_employee_line_user` `e` on(`e`.`line_user_id` = `c`.`user_id`)))select `ranked_checkins`.`id` AS `id`,`ranked_checkins`.`user_id` AS `user_id`,`ranked_checkins`.`display_name` AS `display_name`,`ranked_checkins`.`place_name` AS `place_name`,`ranked_checkins`.`latitude` AS `latitude`,`ranked_checkins`.`longitude` AS `longitude`,`ranked_checkins`.`checkin_time` AS `checkin_time`,`ranked_checkins`.`photo_path` AS `photo_path`,`ranked_checkins`.`check_type` AS `check_type`,`ranked_checkins`.`token_checkin` AS `token_checkin`,`ranked_checkins`.`remark` AS `remark`,`ranked_checkins`.`line_picture_profile` AS `line_picture_profile`,`ranked_checkins`.`emp_name` AS `emp_name`,`ranked_checkins`.`checkin_date` AS `checkin_date`,`ranked_checkins`.`rn_asc` AS `rn_asc`,`ranked_checkins`.`rn_desc` AS `rn_desc` from `ranked_checkins` where `ranked_checkins`.`rn_asc` = 1 or `ranked_checkins`.`rn_desc` = 1 order by `ranked_checkins`.`id` desc;

