DROP VIEW IF EXISTS `v_ims_user`;
CREATE VIEW `v_ims_user` AS select `ims_user`.`id` AS `id`,`ims_user`.`line_no` AS `line_no`,`ims_user`.`user_id` AS `user_id`,`ims_user`.`email` AS `email`,`ims_user`.`first_name` AS `first_name`,`ims_user`.`last_name` AS `last_name`,`ims_user`.`password` AS `password`,`ims_user`.`account_type` AS `account_type`,`ims_user`.`status` AS `status`,`ims_user`.`picture` AS `picture`,`ims_user`.`lang` AS `lang`,`ims_user`.`approve_permission` AS `approve_permission`,`ims_user`.`company` AS `company`,`ims_user`.`manage_team_id` AS `manage_team_id`,`ims_user`.`doc_user_id` AS `doc_user_id`,`ims_user`.`role` AS `role`,`ims_house_line_user`.`line_user_id` AS `line_user_id`,`ims_house_line_user`.`line_user_name` AS `line_user_name`,`ims_house_line_user`.`line_picture_profile` AS `line_picture_profile`,`ims_user`.`user_signature` AS `user_signature` from (`ims_user` left join `ims_house_line_user` on(`ims_house_line_user`.`line_phone` = `ims_user`.`user_id`));

-- ----------------------------
-- View structure for v_inventory_items
-- ----------------------------
DROP VIEW IF EXISTS `v_inventory_items`;
CREATE VIEW `v_inventory_items` AS select `inventory_items`.`id` AS `id`,`inventory_items`.`item_code` AS `item_code`,`inventory_items`.`item_name` AS `item_name`,`inventory_items`.`category_id` AS `category_id`,`inventory_items`.`brand_id` AS `brand_id`,`inventory_items`.`model` AS `model`,`inventory_items`.`received_date` AS `received_date`,`inventory_items`.`status` AS `status`,`inventory_items`.`details` AS `details`,`inventory_items`.`created_at` AS `created_at`,`inventory_items`.`updated_at` AS `updated_at`,`inventory_items`.`file_attach` AS `file_attach`,`m_category`.`category_name` AS `category_name`,`m_brand`.`brand_name` AS `brand_name`,`inventory_items`.`serial_number` AS `serial_number` from ((`inventory_items` left join `m_category` on(`m_category`.`category_id` = `inventory_items`.`category_id`)) left join `m_brand` on(`m_brand`.`brand_id` = `inventory_items`.`brand_id`));

