-- View structure for v_i_payment_voucher
-- ----------------------------
DROP VIEW IF EXISTS `v_i_payment_voucher`;
CREATE VIEW `v_i_payment_voucher` AS select `ims_payment_voucher`.`id` AS `id`,`ims_payment_voucher`.`doc_no` AS `doc_no`,`ims_payment_voucher`.`doc_date` AS `doc_date`,substr(`ims_payment_voucher`.`doc_date`,1,2) AS `doc_day`,`ims_payment_voucher`.`doc_month` AS `doc_month`,`ims_payment_voucher`.`doc_year` AS `doc_year`,`ims_payment_voucher`.`doc_runno` AS `doc_runno`,`ims_payment_voucher`.`requester` AS `requester`,`ims_payment_voucher`.`supplier_id` AS `supplier_id`,`ims_payment_voucher`.`supplier_name` AS `supplier_name`,`ims_payment_voucher`.`purpose` AS `purpose`,`ims_payment_voucher`.`payment_method` AS `payment_method`,`ims_payment_voucher`.`bank_no` AS `bank_no`,`ims_payment_voucher`.`total_amount` AS `total_amount`,`ims_payment_voucher`.`picture_doc` AS `picture_doc`,`ims_payment_voucher`.`create_name` AS `create_name`,`ims_payment_voucher`.`checker_name` AS `checker_name`,`ims_payment_voucher`.`approve_name` AS `approve_name`,`ims_payment_voucher`.`receipt_name` AS `receipt_name`,`ims_payment_voucher`.`approve_status` AS `approve_status`,`ims_payment_voucher`.`status` AS `status`,`ims_payment_voucher`.`create_date` AS `create_date`,`ims_payment_voucher`.`update_date` AS `update_date`,`ims_payment_voucher`.`remark` AS `remark` from `ims_payment_voucher`;

