-- View structure for v_jobrecord
-- ----------------------------
DROP VIEW IF EXISTS `v_jobrecord`;
CREATE VIEW `v_jobrecord` AS select `jobrecord`.`id` AS `id`,`jobrecord`.`user_id` AS `user_id`,`jobrecord`.`emp_id` AS `emp_id`,`jobrecord`.`display_name` AS `display_name`,`jobrecord`.`place_name` AS `place_name`,`jobrecord`.`latitude` AS `latitude`,`jobrecord`.`longitude` AS `longitude`,`jobrecord`.`checkin_time` AS `checkin_time`,`jobrecord`.`photo_path` AS `photo_path`,`jobrecord`.`check_type` AS `check_type`,`jobrecord`.`token_checkin` AS `token_checkin`,`jobrecord`.`remark` AS `remark`,`ims_employee_line_user`.`line_picture_profile` AS `line_picture_profile`,`ims_employee_line_user`.`emp_name` AS `emp_name` from (`jobrecord` left join `ims_employee_line_user` on(`ims_employee_line_user`.`line_user_id` = `jobrecord`.`user_id`));

