-- View structure for v_memployee
-- ----------------------------
DROP VIEW IF EXISTS `v_memployee`;
CREATE VIEW `v_memployee` AS select `memployee`.`id` AS `id`,`memployee`.`emp_id` AS `emp_id`,`memployee`.`sex` AS `sex`,`memployee`.`prefix` AS `prefix`,`memployee`.`f_name` AS `f_name`,`memployee`.`l_name` AS `l_name`,`memployee`.`nick_name` AS `nick_name`,`memployee`.`email_address` AS `email_address`,`memployee`.`phone` AS `phone`,`memployee`.`birthday` AS `birthday`,`memployee`.`position_id` AS `position_id`,`memployee`.`dept_id` AS `dept_id`,`memployee`.`department_id` AS `department_id`,`memployee`.`start_work_date` AS `start_work_date`,`memployee`.`work_time_id` AS `work_time_id`,`memployee`.`status` AS `status`,`memployee`.`remark` AS `remark`,`memployee`.`week_holiday` AS `week_holiday`,`memployee`.`create_date` AS `create_date`,`memployee`.`update_date` AS `update_date`,`memployee`.`dept_id_approve` AS `dept_id_approve`,`mposition`.`position_desc` AS `position_desc`,`mwork_time`.`work_time_detail` AS `work_time_detail`,`memployee`.`image` AS `image`,`memployee`.`salary_type` AS `salary_type`,`memployee`.`salary` AS `salary` from ((`memployee` left join `mposition` on(`mposition`.`position_id` = `memployee`.`position_id`)) left join `mwork_time` on(`mwork_time`.`work_time_id` = `memployee`.`work_time_id`));

SET FOREIGN_KEY_CHECKS = 1;
